import React from 'react';
import { Typography, Card, Row, Col, Button, Space, Alert } from 'antd';
import { 
  RobotOutlined, 
  MessageOutlined, 
  SettingOutlined,
  RocketOutlined,
  FileTextOutlined,
  CrownOutlined,
  BulbOutlined,
  HeartOutlined,
  QuestionCircleOutlined
} from '@ant-design/icons';
import { useNavigate } from 'react-router-dom';

const { Title, Paragraph, Text } = Typography;

interface Prompt {
  id: number;
  name: string;
  description: string;
  category: string;
  is_active: boolean;
  is_base: boolean;
  icon_color?: string;
  usage_count?: number;
  rating?: number;
  created_at?: string;
  updated_at?: string;
}

interface HomeProps {
  onPromptSelect?: (prompt: Prompt) => void;
  selectedPrompt?: Prompt | null;
}

const Home: React.FC<HomeProps> = ({ onPromptSelect, selectedPrompt }) => {
  const navigate = useNavigate();

  return (
    <div className="container home-page">
      {/* Компактная панель действий */}
      <div style={{ 
        marginBottom: 'var(--sp-spacing-sm)', 
        textAlign: 'center',
        padding: 'var(--sp-spacing-xs)'
      }}>
        <Button 
          type="default" 
          size="middle"
          icon={<QuestionCircleOutlined />}
          onClick={() => navigate('/help')}
          style={{
            background: 'var(--sp-bg-secondary)',
            border: '1px solid var(--sp-border-primary)',
            borderRadius: 'var(--sp-border-radius-sm)',
            color: 'var(--sp-text-primary)'
          }}
        >
          📚 Инструкция
        </Button>
      </div>

      {/* Информация о выбранном промпте */}
      {selectedPrompt && (
        <Card 
          style={{ 
            marginBottom: 'var(--sp-spacing-lg)',
            background: 'var(--sp-bg-card)',
            border: '1px solid var(--sp-border-primary)',
            borderRadius: 'var(--sp-border-radius-md)'
          }}
        >
          <div style={{ display: 'flex', alignItems: 'center', gap: '1rem' }}>
            <div style={{ 
              width: '48px', 
              height: '48px', 
              borderRadius: '50%', 
              background: selectedPrompt.icon_color || 'var(--primary-color)',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              fontSize: '24px'
            }}>
              🤖
            </div>
            <div style={{ flex: 1 }}>
              <Title level={4} style={{ margin: '0 0 var(--sp-spacing-xs) 0', color: 'var(--sp-text-primary)' }}>
                Активный промпт: {selectedPrompt.name}
              </Title>
              <Text style={{ color: 'var(--sp-text-secondary)' }}>
                {selectedPrompt.description}
              </Text>
            </div>
            <Button 
              type="primary"
              onClick={() => navigate('/prompts')}
              style={{
                background: 'linear-gradient(135deg, var(--sp-color-primary), var(--sp-color-primary-hover))',
                border: 'none',
                borderRadius: 'var(--sp-border-radius-md)'
              }}
            >
              Изменить
            </Button>
          </div>
        </Card>
      )}

      {/* Основные карточки */}
      <Row gutter={[16, 16]}>
        <Col xs={24} md={12}>
          <Card 
            title={
              <Space>
                <RobotOutlined style={{ color: 'var(--sp-color-primary)' }} />
                <span>LLM настройки</span>
              </Space>
            }
            hoverable
            onClick={() => navigate('/llm-settings')}
            style={{ 
              cursor: 'pointer',
              borderRadius: 'var(--sp-border-radius-md)',
              border: '1px solid var(--sp-border-secondary)',
              background: 'var(--sp-bg-card)'
            }}
            className="feature-card unified-card"
            data-category="llm"
          >
            <Paragraph style={{ color: 'var(--sp-text-secondary)', fontSize: 'var(--sp-font-size-base)', lineHeight: '1.6' }}>
              Выберите и настройте провайдера искусственного интеллекта для вашего Telegram бота.
            </Paragraph>
            <Button 
              type="primary" 
              block
              style={{
                background: 'linear-gradient(135deg, var(--sp-color-primary), var(--sp-color-primary-hover))',
                border: 'none',
                borderRadius: 'var(--sp-border-radius-md)'
              }}
            >
              Настроить LLM
            </Button>
          </Card>
        </Col>

        <Col xs={24} md={12}>
          <Card 
            title={
              <Space>
                <FileTextOutlined style={{ color: 'var(--sp-color-secondary)' }} />
                <span>Личности</span>
              </Space>
            }
            hoverable
            onClick={() => navigate('/prompts')}
            style={{ 
              cursor: 'pointer',
              borderRadius: 'var(--sp-border-radius-md)',
              border: '1px solid var(--sp-border-secondary)',
              background: 'var(--sp-bg-card)'
            }}
            className="feature-card"
          >
            <Paragraph style={{ color: 'var(--sp-text-secondary)', fontSize: 'var(--sp-font-size-base)', lineHeight: '1.6' }}>
              Выберите личности и стили общения для настройки вашего AI-компаньона.
            </Paragraph>
            <Button 
              type="primary" 
              block
              style={{
                background: 'linear-gradient(135deg, var(--sp-color-secondary), var(--sp-color-secondary-hover))',
                border: 'none',
                borderRadius: 'var(--sp-border-radius-md)'
              }}
            >
              Выбрать промпты
            </Button>
          </Card>
        </Col>

        <Col xs={24} md={12}>
          <Card 
            title={
              <Space>
                <MessageOutlined style={{ color: 'var(--sp-color-accent)' }} />
                <span>Чат</span>
              </Space>
            }
            hoverable
            onClick={() => navigate('/chat')}
            style={{ 
              cursor: 'pointer',
              borderRadius: 'var(--sp-border-radius-md)',
              border: '1px solid var(--sp-border-secondary)',
              background: 'var(--sp-bg-card)'
            }}
            className="feature-card"
          >
            <Paragraph style={{ color: 'var(--sp-text-secondary)', fontSize: 'var(--sp-font-size-base)', lineHeight: '1.6' }}>
              Тестируйте общение с AI прямо в Mini App перед использованием в Telegram.
            </Paragraph>
            <Button 
              type="primary" 
              block
              style={{
                background: 'linear-gradient(135deg, var(--sp-color-accent), var(--sp-color-accent-hover))',
                border: 'none',
                borderRadius: 'var(--sp-border-radius-md)'
              }}
            >
              Открыть чат
            </Button>
          </Card>
        </Col>

        <Col xs={24} md={12}>
          <Card 
            title={
              <Space>
                <MessageOutlined style={{ color: 'var(--primary-color)' }} />
                <span>💬 Чат в приложении</span>
              </Space>
            }
            hoverable
            onClick={() => navigate('/mini-chat')}
            style={{ 
              cursor: 'pointer',
              borderRadius: 'var(--sp-border-radius-md)',
              border: '1px solid var(--sp-border-secondary)',
              background: 'var(--sp-bg-card)'
            }}
            className="feature-card"
          >
            <Paragraph style={{ color: 'var(--sp-text-secondary)', fontSize: 'var(--sp-font-size-base)', lineHeight: '1.6' }}>
              Полноценный чат с возможностью удаления сообщений прямо в мини-приложении. Обходит ограничения Telegram!
            </Paragraph>
            <Button 
              type="primary" 
              block
              style={{
                background: 'linear-gradient(135deg, var(--sp-color-primary), var(--sp-color-accent))',
                border: 'none',
                borderRadius: 'var(--sp-border-radius-md)'
              }}
            >
              🚀 Открыть чат в приложении
            </Button>
          </Card>
        </Col>

        <Col xs={24} md={12}>
          <Card 
            title={
              <Space>
                <SettingOutlined style={{ color: 'var(--sp-color-success)' }} />
                <span>Настройки</span>
              </Space>
            }
            hoverable
            onClick={() => navigate('/settings')}
            style={{ 
              cursor: 'pointer',
              borderRadius: 'var(--sp-border-radius-md)',
              border: '1px solid var(--sp-border-secondary)',
              background: 'var(--sp-bg-card)'
            }}
            className="feature-card"
          >
            <Paragraph style={{ color: 'var(--sp-text-secondary)', fontSize: 'var(--sp-font-size-base)', lineHeight: '1.6' }}>
              Управляйте профилем, подпиской и общими настройками приложения.
            </Paragraph>
            <Button 
              type="primary" 
              block
              style={{
                background: 'linear-gradient(135deg, var(--sp-color-success), var(--sp-color-success-hover))',
                border: 'none',
                borderRadius: 'var(--sp-border-radius-md)'
              }}
            >
              Настройки
            </Button>
          </Card>
        </Col>
      </Row>

      {/* Информационный блок */}
      <Alert
        message="Как это работает"
        description={
          <div style={{ marginTop: '1rem' }}>
            <ol style={{ margin: 0, paddingLeft: '1.5rem', lineHeight: '1.8' }}>
              <li><strong>Настройте LLM провайдера</strong> - выберите между GigaChat, OpenAI или DeepSeek</li>
              <li><strong>Выберите промпты</strong> - настройте стиль общения и личности</li>
              <li><strong>Общайтесь в Telegram</strong> - ваш бот будет использовать выбранные настройки</li>
            </ol>
          </div>
        }
        type="info"
        showIcon
        style={{ 
          marginTop: '1.5rem',
          borderRadius: 'var(--sp-border-radius-md)',
          border: '1px solid var(--sp-border-secondary)'
        }}
        icon={<BulbOutlined style={{ color: 'var(--sp-color-accent)' }} />}
      />

      {/* Кнопка начала */}
      <div style={{ textAlign: 'center', marginTop: '1.5rem' }}>
        <Button 
          type="primary" 
          size="large" 
          icon={<RocketOutlined />}
          onClick={() => navigate('/llm-settings')}
          style={{
            background: 'linear-gradient(135deg, var(--sp-color-primary), var(--sp-color-secondary))',
            border: 'none',
            borderRadius: 'var(--sp-border-radius-md)',
            padding: 'var(--sp-spacing-md) var(--sp-spacing-xl)',
            fontSize: 'var(--sp-font-size-lg)',
            height: 'auto'
          }}
        >
          Начать настройку
        </Button>
      </div>

      {/* Дополнительная информация */}
      <Row gutter={[16, 16]} style={{ marginTop: '2rem' }}>
        <Col xs={24} md={8}>
          <Card 
            style={{ 
              textAlign: 'center',
              borderRadius: 'var(--sp-border-radius-md)',
              border: '1px solid var(--sp-border-secondary)',
              background: 'var(--sp-bg-card)'
            }}
          >
            <CrownOutlined style={{ 
              fontSize: 'var(--sp-font-size-2xl)', 
              color: 'var(--sp-color-accent)',
              marginBottom: 'var(--sp-spacing-md)'
            }} />
            <Title level={4} style={{ color: 'var(--sp-text-primary)' }}>
              Премиум функции
            </Title>
            <Paragraph style={{ color: 'var(--sp-text-secondary)' }}>
              Расширенные возможности для профессионального использования
            </Paragraph>
          </Card>
        </Col>

        <Col xs={24} md={8}>
          <Card 
            style={{ 
              textAlign: 'center',
              borderRadius: 'var(--sp-border-radius-md)',
              border: '1px solid var(--sp-border-secondary)',
              background: 'var(--sp-bg-card)'
            }}
          >
            <HeartOutlined style={{ 
              fontSize: 'var(--sp-font-size-2xl)', 
              color: 'var(--sp-color-success)',
              marginBottom: 'var(--sp-spacing-md)'
            }} />
            <Title level={4} style={{ color: 'var(--sp-text-primary)' }}>
              Персональный подход
            </Title>
            <Paragraph style={{ color: 'var(--sp-text-secondary)' }}>
              Настройка под ваши индивидуальные потребности и стиль
            </Paragraph>
          </Card>
        </Col>

        <Col xs={24} md={8}>
          <Card 
            style={{ 
              textAlign: 'center',
              borderRadius: 'var(--sp-border-radius-md)',
              border: '1px solid var(--sp-border-secondary)',
              background: 'var(--sp-bg-card)'
            }}
          >
            <BulbOutlined style={{ 
              fontSize: 'var(--sp-font-size-2xl)', 
              color: 'var(--sp-color-primary)',
              marginBottom: 'var(--sp-spacing-md)'
            }} />
            <Title level={4} style={{ color: 'var(--sp-text-primary)' }}>
              Умные решения
            </Title>
            <Paragraph style={{ color: 'var(--sp-text-secondary)' }}>
              ИИ-помощник для решения сложных задач и творческих проектов
            </Paragraph>
          </Card>
        </Col>
      </Row>
    </div>
  );
};

export default Home;
